<?php

namespace Tests\Unit\Services\Print;

use App\Services\Print\ProxyShipmentOutboundPdfService;
use PHPUnit\Framework\TestCase;
use RuntimeException;
use setasign\Fpdi\PdfParser\StreamReader;
use setasign\Fpdi\Tcpdf\Fpdi;
use Smalot\PdfParser\Parser;

class ProxyShipmentOutboundPdfServiceTest extends TestCase
{
    private function source(): string
    {
        // Synthetic documents only; generated by the unchanged core TCPDF renderer.
        return file_get_contents(__DIR__.'/../../../Fixtures/Print/multiple-transfer-multipage.pdf');
    }

    private function reordered(array $numbers): string
    {
        $pdf = new Fpdi;
        $pdf->setPrintHeader(false);
        $pdf->setPrintFooter(false);
        $pdf->setSourceFile(StreamReader::createByString($this->source()));
        foreach ($numbers as $number) {
            $pdf->AddPage();
            $pdf->useTemplate($pdf->importPage($number));
        }

        return $pdf->Output('', 'S');
    }

    public function test_extracts_all_outbound_continuation_pages_for_multiple_transfers(): void
    {
        $source = $this->source();
        $hash = hash('sha256', $source);
        $output = (new ProxyShipmentOutboundPdfService)->extract($source, ['2000', '3000']);
        $pages = (new Parser)->parseContent($output)->getPages();
        $this->assertCount(3, $pages);
        foreach ($pages as $page) {
            $text = preg_replace('/\s+/u', '', $page->getText());
            $this->assertStringContainsString('転送伝票（出庫用）', $text);
            $this->assertStringNotContainsString('転送伝票（入庫用）', $text);
        }
        $this->assertStringContainsString('試験商品15', preg_replace('/\s+/u', '', $pages[2]->getText()));
        $this->assertSame($hash, hash('sha256', $source));
    }

    public function test_rejects_a_pdf_for_different_selected_documents(): void
    {
        $this->expectException(RuntimeException::class);
        (new ProxyShipmentOutboundPdfService)->extract($this->source(), ['2000', '9999']);
    }

    public function test_rejects_interleaved_inbound_and_outbound_pages(): void
    {
        $this->expectException(RuntimeException::class);
        (new ProxyShipmentOutboundPdfService)->extract($this->reordered([1, 4, 2, 5, 3, 6]), ['2000', '3000']);
    }

    public function test_rejects_missing_or_odd_pages(): void
    {
        $this->expectException(RuntimeException::class);
        (new ProxyShipmentOutboundPdfService)->extract($this->reordered([1, 2, 4]), ['2000', '3000']);
    }

    public function test_rejects_broken_pdf_instead_of_returning_the_inbound_copy(): void
    {
        $this->expectException(\Throwable::class);
        (new ProxyShipmentOutboundPdfService)->extract('%PDF-invalid', ['2000']);
    }
}
